"""تجهيز مشروع APK للعبة حرب حمص (يعمل داخل GitHub Actions) — الإصدار 2
   python3 prepare_app.py web      ← ينسخ اللعبة ويحمّل المكتبات والخطوط لتعمل بسرعة وبدون إنترنت
   python3 prepare_app.py android  ← أفقي + ملء الشاشة + أيقونة جامع خالد بن الوليد + شاشة مضاءة """
import os, re, sys, base64, hashlib, urllib.request

UA = 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Mobile Safari/537.36'
LIBS = {
    'https://unpkg.com/peerjs@1.5.4/dist/peerjs.min.js': 'peerjs.min.js',
    'https://cdn.jsdelivr.net/npm/three@0.147.0/build/three.min.js': 'three.min.js',
    'https://cdn.jsdelivr.net/npm/mqtt@5.10.1/dist/mqtt.min.js': 'mqtt.min.js',
}
BG_COLOR = '#090603'

# أيقونات التطبيق (شعار جامع خالد بن الوليد) بكل الأحجام — مضغوطة داخل الملف
ICONS = {"mdpi/ic_launcher":"","mdpi/ic_launcher_round":"","mdpi/ic_launcher_foreground":"","hdpi/ic_launcher":"","hdpi/ic_launcher_round":"","hdpi/ic_launcher_foreground":"","xhdpi/ic_launcher":"","xhdpi/ic_launcher_round":"","xhdpi/ic_launcher_foreground":"","xxhdpi/ic_launcher":"","xxhdpi/ic_launcher_round":"","xxhdpi/ic_launcher_foreground":"","xxxhdpi/ic_launcher":"","xxxhdpi/ic_launcher_round":"","xxxhdpi/ic_launcher_foreground":""}

def fetch(url, timeout=60):
    req = urllib.request.Request(url, headers={'User-Agent': UA})
    return urllib.request.urlopen(req, timeout=timeout).read()

def bundle_fonts(s):
    """تحميل خطوط Google محلياً حتى لا تتأخر اللعبة بانتظار الإنترنت (يتجاوز الخطأ بأمان)"""
    m = re.search(r'<link href="(https://fonts\.googleapis\.com/css2[^"]+)" rel="stylesheet">', s)
    if not m:
        return s
    try:
        css = fetch(m.group(1)).decode('utf-8')
        os.makedirs('www/fonts', exist_ok=True)
        def rep(mm):
            url = mm.group(1)
            name = hashlib.md5(url.encode()).hexdigest()[:12] + '.woff2'
            open('www/fonts/' + name, 'wb').write(fetch(url))
            return 'url(' + name + ')'
        css2 = re.sub(r'url\((https://fonts\.gstatic\.com/[^)]+)\)', rep, css)
        open('www/fonts/fonts.css', 'w', encoding='utf-8').write(css2)
        s = s.replace(m.group(0), '<link rel="stylesheet" href="fonts/fonts.css">')
        s = s.replace('<link rel="preconnect" href="https://fonts.googleapis.com">', '')
        s = s.replace('<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>', '')
        print('fonts bundled')
    except Exception as e:
        print('skip fonts (تبقى من الإنترنت):', e)
    return s

def web():
    os.makedirs('www/lib', exist_ok=True)
    htmls = sorted(f for f in os.listdir('.') if f.lower().endswith('.html'))
    others = [f for f in htmls if f != 'index.html'] or htmls
    def rank(name):
        # الأحدث: الذي يحتوي إعدادات حساب جوجل أولاً، ثم الأكبر رقماً في الاسم (مثل -15)
        try:
            has = 1 if 'HOMS_FIREBASE' in open(name, encoding='utf-8', errors='ignore').read() else 0
        except Exception:
            has = 0
        nums = [int(x) for x in re.findall(r'\d+', name)]
        return (has, nums, name)
    src = max(others, key=rank)
    print('game file:', src)
    s = open(src, encoding='utf-8').read()
    for url, name in LIBS.items():
        try:
            data = fetch(url)
            if len(data) < 10000:
                raise ValueError('ملف صغير جداً')
            open('www/lib/' + name, 'wb').write(data)
            s = s.replace(url, 'lib/' + name)
            print('bundled', name, len(data))
        except Exception as e:
            print('skip (يبقى من الإنترنت):', url, e)
    s = bundle_fonts(s)
    open('www/index.html', 'w', encoding='utf-8').write(s)

MAIN_ACTIVITY = '''package com.homswar.game;

import android.os.Bundle;
import android.view.View;
import android.view.WindowManager;
import com.getcapacitor.BridgeActivity;

public class MainActivity extends BridgeActivity {
    @Override
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
        hideBars();
    }
    @Override
    public void onWindowFocusChanged(boolean hasFocus) {
        super.onWindowFocusChanged(hasFocus);
        if (hasFocus) hideBars();
    }
    private void hideBars() {
        getWindow().getDecorView().setSystemUiVisibility(
            View.SYSTEM_UI_FLAG_LAYOUT_STABLE
            | View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION
            | View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
            | View.SYSTEM_UI_FLAG_HIDE_NAVIGATION
            | View.SYSTEM_UI_FLAG_FULLSCREEN
            | View.SYSTEM_UI_FLAG_IMMERSIVE_STICKY);
    }
}
'''

ADAPTIVE_XML = '''<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
    <background android:drawable="@color/ic_launcher_background"/>
    <foreground android:drawable="@mipmap/ic_launcher_foreground"/>
</adaptive-icon>
'''

def put_icons():
    res = 'android/app/src/main/res/'
    for key, b64 in ICONS.items():
        dens, name = key.split('/')
        d = res + 'mipmap-' + dens
        os.makedirs(d, exist_ok=True)
        open(d + '/' + name + '.png', 'wb').write(base64.b64decode(b64))
    os.makedirs(res + 'values', exist_ok=True)
    open(res + 'values/ic_launcher_background.xml', 'w', encoding='utf-8').write(
        '<?xml version="1.0" encoding="utf-8"?>\n<resources>\n'
        '    <color name="ic_launcher_background">' + BG_COLOR + '</color>\n</resources>\n')
    os.makedirs(res + 'mipmap-anydpi-v26', exist_ok=True)
    for n in ('ic_launcher.xml', 'ic_launcher_round.xml'):
        open(res + 'mipmap-anydpi-v26/' + n, 'w', encoding='utf-8').write(ADAPTIVE_XML)
    print('icons written')

def patch_signing():
    """توقيع التطبيق بمفتاح ثابت (سر GitHub) ليبقى SHA-1 ثابتاً ويعمل تسجيل الدخول بجوجل"""
    ks = os.environ.get('KS_PATH', '')
    if not ks or not os.path.exists(ks):
        print('no signing key: using default debug key')
        return
    g = 'android/app/build.gradle'
    t = open(g, encoding='utf-8').read()
    if 'signingConfigs.homswar' in t:
        return
    block = ("android {\n    signingConfigs {\n        homswar {\n"
             "            storeFile file(System.getenv('KS_PATH'))\n"
             "            storePassword System.getenv('KS_PASS')\n"
             "            keyAlias 'homswar'\n"
             "            keyPassword System.getenv('KS_PASS')\n        }\n    }\n")
    t = re.sub(r'android\s*\{\n', lambda m: block, t, count=1)
    t = re.sub(r'buildTypes\s*\{\n', lambda m: "buildTypes {\n        debug { signingConfig signingConfigs.homswar }\n", t, count=1)
    open(g, 'w', encoding='utf-8').write(t)
    print('signing patched')

def patch_google_services():
    """نسخ google-services.json وتفعيل إضافة جوجل (إن وُجد الملف)"""
    if not os.path.exists('google-services.json'):
        print('no google-services.json: Google sign-in in the app is disabled')
        return
    import shutil
    shutil.copy('google-services.json', 'android/app/google-services.json')
    rb = 'android/build.gradle'
    t = open(rb, encoding='utf-8').read()
    if 'com.google.gms:google-services' not in t:
        t = re.sub(r"(classpath 'com\.android\.tools\.build:gradle[^\n]*\n)",
                   lambda m: m.group(1) + "        classpath 'com.google.gms:google-services:4.4.2'\n", t, count=1)
        open(rb, 'w', encoding='utf-8').write(t)
    ab = 'android/app/build.gradle'
    a = open(ab, encoding='utf-8').read()
    if "com.google.gms.google-services" not in a:
        a += "\napply plugin: 'com.google.gms.google-services'\n"
        open(ab, 'w', encoding='utf-8').write(a)
    print('google-services ready')

def patch_cap_config():
    """إعداد إضافة تسجيل الدخول (جوجل بدون مصادقة أصلية؛ يتولاها Firebase داخل اللعبة)"""
    import json
    p = 'capacitor.config.json'
    if not os.path.exists(p) or not os.path.exists('google-services.json'):
        return
    c = json.load(open(p, encoding='utf-8'))
    c.setdefault('plugins', {})['FirebaseAuthentication'] = {'skipNativeAuth': True, 'providers': ['google.com']}
    json.dump(c, open(p, 'w', encoding='utf-8'), ensure_ascii=False, indent=2)
    print('capacitor config patched')

def android():
    man = 'android/app/src/main/AndroidManifest.xml'
    m = open(man, encoding='utf-8').read()
    if 'screenOrientation' not in m:
        m = m.replace('<activity', '<activity android:screenOrientation="sensorLandscape"', 1)
    if 'largeHeap' not in m:
        m = m.replace('<application', '<application android:largeHeap="true"', 1)
    open(man, 'w', encoding='utf-8').write(m)

    st = 'android/app/src/main/res/values/styles.xml'
    t = open(st, encoding='utf-8').read()
    add = ('<item name="android:windowFullscreen">true</item>'
           '<item name="android:windowLayoutInDisplayCutoutMode">shortEdges</item>')
    t = re.sub(r'(<style name="AppTheme\.NoActionBar"[^>]*>)', lambda g: g.group(1) + add, t, count=1)
    t = t.replace('@drawable/splash', '@color/ic_launcher_background')   # شاشة إقلاع داكنة بدل شعار Capacitor
    open(st, 'w', encoding='utf-8').write(t)

    try:
        put_icons()
    except Exception as e:
        print('icons skipped:', e)

    for fn in (patch_signing, patch_google_services, patch_cap_config):
        try:
            fn()
        except Exception as e:
            print('skip', fn.__name__, e)

    d = 'android/app/src/main/java/com/homswar/game'
    os.makedirs(d, exist_ok=True)
    open(d + '/MainActivity.java', 'w', encoding='utf-8').write(MAIN_ACTIVITY)
    print('android patched')

if __name__ == '__main__':
    {'web': web, 'android': android}[sys.argv[1]]()
